omni = '''<div class="two"><div class="pnl bad"><p class="cap">Shared omnibus account</p><div class="lane"><span class="lbl">Pooled securities</span><span class="tok">Client A buy: in</span><span class="tok ghost">Client B sell: delivery</span><span class="warn">Cross-settlement</span></div><p class="n">Securities bought for Client A can be used to meet Client B&rsquo;s delivery, because they sit in the same pool.</p></div>
<div class="pnl good"><p class="cap">Dedicated, segregated accounts</p><div class="lane"><span class="lbl">Client A account</span><span class="tok">Client A securities</span></div><div class="lane"><span class="lbl">Client B account</span><span class="tok b">Client B securities</span></div><p class="n">Each client&rsquo;s securities stay in their own designated Euroclear account, identified to them.</p></div></div>'''
gap = '''<div class="two"><div class="pnl bad"><p class="cap">Without linked instructions</p><div class="lk"><div class="rowx"><span>Buy</span><div class="trk"><span class="seg buy" style="left:0;width:30%">Settles</span></div></div><div class="rowx"><span>Sell</span><div class="trk"><span class="seg pend" style="left:30%;width:62%">Fails to settle</span></div></div><div class="rowx"><span>You</span><div class="trk"><span class="seg fin" style="left:30%;width:62%">Financing</span></div></div></div><div class="axis"><span>T</span><span>T+1</span><span>T+2</span><span>T+3</span></div></div>
<div class="pnl good"><p class="cap">With EMFI linked instructions</p><div class="lk"><div class="rowx"><span>Buy</span><div class="trk"><span class="seg hold" style="left:0;width:62%">Held back</span><span class="seg buy" style="left:62%;width:30%">Settles</span></div></div><div class="rowx"><span>Sell</span><div class="trk"><span class="seg pend" style="left:0;width:62%">Not ready</span><span class="seg sell" style="left:62%;width:30%">Settles</span></div></div><div class="rowx"><span>You</span><div class="trk"><span class="seg" style="left:0;width:100%;color:var(--teal)">No interim financing</span></div></div></div><div class="axis"><span>T</span><span>T+1</span><span>T+2</span><span>T+3</span></div></div></div><p class="fine" style="margin-top:16px;color:var(--mute)">Simplified illustration of the mechanism. It is not a guarantee of settlement.</p>'''
